using Parts=std::vector<DiscoveryWorkbenchPart>;
inline std::string call(const std::string& arg,const std::string& keywords="[]"){return "{\"schema\":\"minera-pandas-variants-original-call-v1\",\"args\":["+arg+"],\"keyword_entries\":"+keywords+'}';}
inline Parts request(const EventTable& source,const std::string& op,const std::string& json){return {field("engine","pandas"),field("operation",op),{"source_file","source.json",serialize_embedding_workbench_table_json(source),true},field("call_json",json)};}
inline void envelope(const DiscoveryWorkbenchResponse& r){const auto node=o::shared::Reader(r.json).read();std::set<std::string> fields;for(const auto& [name,value]:node.fields){(void)value;fields.insert(name);}require(fields==std::set<std::string>{"family","engine","operation","http_status","phase","apply_returned","source","result","source_unchanged","case_id_key","attribute_key","timestamp_key","source_table_json","filtered_table_json","variants_table_json","variants_source_unchanged","error_type","error","call_mode","call_json","controls_before_json","controls_after_json","controls_unchanged","source_after_table_json"},"original response is not exact24");}
inline void preserved(const DiscoveryWorkbenchResponse& r,const EventTable& source,const std::string& json){envelope(r);require(text(r.json,"call_json")==json,"original call bytes changed");const auto saved=serialize_embedding_workbench_table_json(source);require(text(r.json,"source_table_json")==saved&&text(r.json,"source_after_table_json")==saved,"full source before/after lost");require(text(r.json,"controls_before_json")==text(r.json,"controls_after_json"),"actual caller controls changed");contains(r,"\"controls_unchanged\":true");contains(r,"\"case_id_key\":null,\"attribute_key\":null,\"timestamp_key\":null");}
